software Library {
  metadata { displayName "Library"; namespace "example.crudaccess"; }
  target { language java 21; framework spring_boot; persistence mybatis_plus; database mysql; build maven; interface rest; }
  sources { }
  imports { }
  declarations {
    enum Role { READER, ADMIN }

    entity User persistent {
      identity id: Id generated auto;
      field role: Role default Role.READER;
    }

    entity AccessToken persistent {
      identity id: Token generated uuid;
      field owner: Ref<User>;
      field expiresAt: Moment;
      credential subject owner expires expiresAt;
    }

    entity Book persistent {
      identity id: Id generated auto;
      field title: Text where length(1, 64);
      field stock: Count default 5;
    }

    entity Post persistent {
      identity id: Id generated auto;
      field author: Ref<User>;
      field body: Text where length(1, 255);
      field state: Code default "open";
      field version: Version versioned;
    }

    input BookCreateInput {
      field title: Text where length(1, 64);
    }

    input BookUpdateInput {
      field id: Id;
      field title: Text where length(1, 64);
    }

    input BookIdInput {
      field id: Id;
    }

    input BookListInput {
      field page: PageNo;
      field size: PageSize;
    }

    input PostCreateInput {
      field body: Text where length(1, 255);
    }

    input PostUpdateInput patch of Post {
      field id: Id;
      field body: Text where length(1, 255);
    }

    input PostIdInput {
      field id: Id;
    }

    input PostListInput {
      field page: PageNo;
      field size: PageSize;
    }

    view BookView from Book {
      field id: Id;
      field title: Text;
      field stock: Count;
    }

    view PostView from Post {
      field id: Id;
      field author: Ref<User>;
      field body: Text;
      field state: Code;
      field version: Version;
    }

    error BookNotFound http 404;
    error PostNotFound http 404;
    error StalePost http 409;
    error Forbidden http 403;

    capability CreateBook {
      actor Ref<User>;
      input BookCreateInput;
      output BookView;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command at "/library/books";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        create Book as made {
          title: input.title;
        }
        persist made;
        return made;
      }
    }

    capability GetBook {
      input BookIdInput;
      output BookView;
      fails BookNotFound;
      requires readonly;
      expose query at "/library/books/{id}";
      workflow {
        load Book by input.id as found else BookNotFound;
        return found;
      }
    }

    capability ListBook {
      input BookListInput;
      output Page<BookView>;
      requires readonly;
      expose query at "/library/books";
      workflow {
        find Book where true order by id ascending Page input.page, input.size as rows;
        return rows;
      }
    }

    capability UpdateBook {
      actor Ref<User>;
      input BookUpdateInput;
      output BookView;
      fails BookNotFound;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command put at "/library/books/{id}";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load Book by input.id as found else BookNotFound;
        update found {
          title: input.title;
        }
        persist found;
        return found;
      }
    }

    capability DeleteBook {
      actor Ref<User>;
      input BookIdInput;
      output Unit;
      fails BookNotFound;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command delete at "/library/books/{id}";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load Book by input.id as found else BookNotFound;
        delete found;
        return unit;
      }
    }

    capability CreatePost {
      actor Ref<User>;
      input PostCreateInput;
      output PostView;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command at "/public/posts";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        create Post as made {
          author: actor;
          body: input.body;
        }
        persist made;
        return made;
      }
    }

    capability GetPost {
      input PostIdInput;
      output PostView;
      fails PostNotFound;
      requires readonly;
      expose query at "/public/posts/{id}";
      workflow {
        load Post by input.id as found else PostNotFound;
        validate found.state != "hidden" else PostNotFound;
        return found;
      }
    }

    capability ListPost {
      input PostListInput;
      output Page<PostView>;
      requires readonly;
      expose query at "/public/posts";
      workflow {
        find Post where item.state != "hidden" order by id ascending Page input.page, input.size as rows;
        return rows;
      }
    }

    capability UpdatePost {
      actor Ref<User>;
      input PostUpdateInput;
      output PostView;
      fails PostNotFound;
      fails StalePost;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command at "/public/posts/{id}";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load Post by input.id as found else PostNotFound;
        validate found.author == actor else PostNotFound;
        update found {
          body: input.body;
        }
        persist found else StalePost;
        return found;
      }
    }

    capability DeletePost {
      actor Ref<User>;
      input PostIdInput;
      output Unit;
      fails PostNotFound;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command delete at "/public/posts/{id}";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load Post by input.id as found else PostNotFound;
        validate found.author == actor else PostNotFound;
        delete found;
        return unit;
      }
    }
  }
}

